def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Grid lines are the strongly non-background rows and columns.
    row_scores = [sum(v != bg for v in row) for row in grid]
    col_scores = [sum(grid[r][c] != bg for r in range(h)) for c in range(w)]
    rows = [r for r, s in enumerate(row_scores) if s > w // 2]
    cols = [c for c, s in enumerate(col_scores) if s > h // 2]

    if not rows or not cols:
        return [[bg]]

    vals = [[grid[r][c] for c in cols] for r in rows]
    baseline = Counter(v for row in vals for v in row).most_common(1)[0][0]

    # Mark one cell per connected component of each non-baseline color.
    a = [[bg for _ in cols] for _ in rows]
    seen = set()
    for i in range(len(rows)):
        for j in range(len(cols)):
            color = vals[i][j]
            if color == baseline or (i, j) in seen:
                continue
            q = [(i, j)]
            seen.add((i, j))
            while q:
                x, y = q.pop()
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if (0 <= nx < len(rows) and 0 <= ny < len(cols)
                            and (nx, ny) not in seen and vals[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            a[i][j] = color

    while a and all(v == bg for v in a[-1]):
        a.pop()
    while a and all(row[-1] == bg for row in a):
        for row in a:
            row.pop()
    return a
